app.use('/api/*',async(c,next)=>{const suppliedRequestId=c.req.header('x-request-id'),requestId=suppliedRequestId&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(suppliedRequestId)?suppliedRequestId:crypto.randomUUID();c.set('requestId',requestId);c.header('X-Request-Id',requestId);const started=Date.now();let status=500;try{const config=parseEnv(c.env);c.set('config',config);const origin=c.req.header('origin');if(origin&&!config.origins.has(origin))throw new HttpError(403,'Origin not allowed','cors');if(origin){c.header('Access-Control-Allow-Origin',origin);c.header('Access-Control-Allow-Credentials','true');c.header('Vary','Origin');}if(c.req.method==='OPTIONS'){c.header('Access-Control-Allow-Methods','GET,POST,PUT,PATCH,DELETE,OPTIONS');c.header('Access-Control-Allow-Headers','Authorization,Content-Type,X-Request-Id');c.header('Access-Control-Max-Age','86400');status=204;return c.body(null,204);}await next();status=c.res.status;}catch(e){const response=errorResponse(c,e);status=response.status;c.res=response;}finally{console.log(JSON.stringify({requestId,route:c.req.routePath||'unmatched',method:c.req.method,status,durationMs:Date.now()-started,environment:c.env.APP_ENV||'unknown'}));}});

