const bearer=(c:Context<AppBindings>)=>c.req.header('authorization')?.startsWith('Bearer ')?c.req.header('authorization')!.slice(7):'';
const equal=(a:string,b:string)=>{const x=new TextEncoder().encode(a),y=new TextEncoder().encode(b);let d=x.length^y.length;for(let i=0;i<Math.max(x.length,y.length);i++)d|=(x[i%x.length]??0)^(y[i%y.length]??0);return d===0;};
const cookie=(c:Context<AppBindings>,name:string)=>c.req.header('cookie')?.split(';').map(v=>v.trim()).find(v=>v.startsWith(`${name}=`))?.slice(name.length+1);

app.post('/api/setup/bootstrap',async c=>{const cfg=c.get('config');if(!cfg.BOOTSTRAP_TOKEN||!cfg.BOOTSTRAP_ADMIN_EMAIL||!cfg.BOOTSTRAP_ADMIN_PASSWORD)throw new HttpError(404,'Not Found');await limit(cfg.DB,cfg.RATE_LIMIT_HMAC_SECRET,'bootstrap',c.req.header('cf-connecting-ip'),5,900);if((await c.req.arrayBuffer()).byteLength)throw new HttpError(400,'Request body must be empty');if(!equal(bearer(c),cfg.BOOTSTRAP_TOKEN))throw new HttpError(401,'Unauthorized');validatePassword(cfg.BOOTSTRAP_ADMIN_PASSWORD);const email=cfg.BOOTSTRAP_ADMIN_EMAIL.trim().toLowerCase();if(!/^\S+@\S+\.\S+$/.test(email)||email.length>254)throw new HttpError(503,'Configuration unavailable');if(await one(cfg.DB.prepare('SELECT id FROM bootstrap_state WHERE id=1')))throw new HttpError(409,'Bootstrap already completed');const hash=await hashPassword(cfg.BOOTSTRAP_ADMIN_PASSWORD),ts=nowIso();const statements=[cfg.DB.prepare("INSERT INTO admin_users(name,email,password_hash,is_active,created_at,role,view_only) VALUES('System Administrator',?,?,1,?,'SUPER_ADMIN',0)").bind(email,hash,ts),cfg.DB.prepare('INSERT INTO bootstrap_state(id,completed_at,admin_user_id) SELECT 1,?,id FROM admin_users WHERE lower(email)=?').bind(ts,email)];try{await batch(cfg.DB,statements);}catch{throw new HttpError(409,'Bootstrap already completed');}return c.json({success:true,message:'Bootstrap completed'},201);});

app.post('/api/auth/admin/login',async c=>{const cfg=c.get('config'),body=await jsonBody(c);checkUnknown(body,['email','password']);const email=validEmail(body.email),password=requiredString(body,'password',128);if([...password].length<12)throw new HttpError(400,'Invalid credentials');await limitAdminLogin(cfg.DB,cfg.RATE_LIMIT_HMAC_SECRET,c.req.header('cf-connecting-ip'),email);const user=await one<{id:number;email:string;name:string|null;password_hash:string;is_active:number;role:string;view_only:number}>(cfg.DB.prepare('SELECT id,email,name,password_hash,is_active,role,view_only FROM admin_users WHERE lower(email)=?').bind(email));const ok=await verifyPassword(password,user?.password_hash??getDummyPasswordRecord());if(!user||!ok||!user.is_active)throw new HttpError(401,'Invalid email or password');const p=await permissions(cfg.DB,user),t=await tokens(cfg,user,'admin',p);await run(cfg.DB.prepare('UPDATE admin_users SET last_login_at=? WHERE id=?').bind(nowIso(),user.id));c.header('Set-Cookie',refreshCookie(cfg,t.refreshToken));return c.json({accessToken:t.accessToken,user:{id:user.id,email:user.email,name:user.name,role:user.role,viewOnly:Boolean(user.view_only),...p}});});

app.post('/api/auth/login',async c=>{const cfg=c.get('config'),body=await jsonBody(c);checkUnknown(body,['mobile']);const mobile=requiredString(body,'mobile',50).replace(/^(?:\+966|966|0)/,'');if(!/^5\d{8}$/.test(mobile))throw new HttpError(400,'Invalid mobile number');const ts=nowIso();await run(cfg.DB.prepare('INSERT INTO users(phone_number,is_active,created_at,updated_at,last_login_at) VALUES(?,1,?,?,?) ON CONFLICT(phone_number) DO UPDATE SET last_login_at=excluded.last_login_at,updated_at=excluded.updated_at').bind(mobile,ts,ts,ts));const user=await one<{id:number;phone_number:string;is_active:number}>(cfg.DB.prepare('SELECT id,phone_number,is_active FROM users WHERE phone_number=?').bind(mobile));if(!user?.is_active)throw new HttpError(401,'Unauthorized');const t=await tokens(cfg,user,'user');c.header('Set-Cookie',refreshCookie(cfg,t.refreshToken));return c.json({accessToken:t.accessToken,user:{id:user.id,phoneNumber:user.phone_number}});});

app.post('/api/auth/refresh',async c=>{const cfg=c.get('config');const origin=c.req.header('origin');if(origin&&!cfg.origins.has(origin))throw new HttpError(403,'Origin not allowed');const token=cookie(c,'refreshToken');if(!token)throw new HttpError(401,'Unauthorized');const claim=await verifyJwt(cfg.JWT_REFRESH_SECRET,token);if(claim.kind==='admin'){const user=await one<{id:number;role:string;view_only:number;is_active:number;email:string;name:string|null}>(cfg.DB.prepare('SELECT id,role,view_only,is_active,email,name FROM admin_users WHERE id=?').bind(claim.sub));if(!user?.is_active)throw new HttpError(401,'Unauthorized');const p=await permissions(cfg.DB,user),t=await tokens(cfg,user,'admin',p);c.header('Set-Cookie',refreshCookie(cfg,t.refreshToken));return c.json({accessToken:t.accessToken,user:{id:user.id,email:user.email,name:user.name,role:user.role,viewOnly:Boolean(user.view_only),...p}});}const user=await one<{id:number;phone_number:string;is_active:number}>(cfg.DB.prepare('SELECT id,phone_number,is_active FROM users WHERE id=?').bind(claim.sub));if(!user?.is_active)throw new HttpError(401,'Unauthorized');const t=await tokens(cfg,user,'user');c.header('Set-Cookie',refreshCookie(cfg,t.refreshToken));return c.json({accessToken:t.accessToken,user:{id:user.id,phoneNumber:user.phone_number}});});
app.post('/api/auth/logout',c=>{c.header('Set-Cookie',refreshCookie(c.get('config'),'',0));return c.json({success:true,message:'Logged out successfully'});});

