app.get('/api/auth/admin/users',auth,requirePermission('AUTH','USER_MANAGEMENT'),async c=>{const {page,limit,offset}=listQuery(c),db=c.get('config').DB,total=await one<{n:number}>(db.prepare('SELECT count(*) n FROM admin_users')),rows=(await all<Record<string,unknown>>(db.prepare('SELECT id,name,email,is_active,created_at,last_login_at,role,store_id,view_only FROM admin_users ORDER BY id LIMIT ? OFFSET ?').bind(limit,offset))).map(camel);return c.json({success:true,count:total?.n??0,page,limit,totalPages:Math.ceil((total?.n??0)/limit),data:rows});});
