  const fields=mode==='standard'?serviceCreateFields:mode==='manual'?serviceManualFields:serviceUpdateFields;checkUnknown(body,fields);
  const required=mode==='standard'?['name','mobile','device','deviceDisplayName','locationType','location','language','dateTime']:mode==='manual'?['name','mobile','device','location']:[];
