async function createBill(c:Context<AppBindings>){
  const b=await jsonBody(c);checkUnknown(b,['serviceRequestId','id','costPrice','customerPrice','sellingPrice','mobile','notes','userId']);
  if(b.serviceRequestId!==undefined&&b.id!==undefined&&String(b.serviceRequestId)!==String(b.id))throw new HttpError(400,'Conflicting service request IDs');
  const requestId=id(String(b.serviceRequestId??b.id??''));
  if(typeof b.costPrice!=='string'||typeof (b.customerPrice??b.sellingPrice)!=='string')throw new HttpError(400,'Prices must be strings');
  optionalStringField(b,'mobile',50);optionalStringField(b,'notes',10000);
  const request=await one<{name:string;mobile:string}>(c.get('config').DB.prepare('SELECT name,mobile FROM service_requests WHERE id=?').bind(requestId));if(!request)throw new HttpError(404,'Service request not found');
  const r=await run(c.get('config').DB.prepare('INSERT INTO bills(user_id,cost_price_halalas,selling_price_halalas,mobile,notes,name,created_at) VALUES(?,?,?,?,?,?,?) RETURNING *').bind(requestId,money(b.costPrice),money(b.customerPrice??b.sellingPrice),b.mobile??request.mobile,b.notes??null,request.name,nowIso()));
  return c.json({success:true,message:'Bill created successfully',data:camel(r.results![0] as Record<string,unknown>)},201);
}
