async function accessible(claims:Claims,type:string){return claims.role==='SUPER_ADMIN'||(type==='new-request'?claims.modules?.includes('CLIENTS')&&claims.submodules?.includes('SERVICE_REQUESTS'):claims.modules?.includes('ORGANIZATION')&&claims.submodules?.includes('STAFF'));}
app.get('/api/notifications',auth,async c=>{const afterText=c.req.query('after')??'0',limitText=c.req.query('limit')??'50',after=Number(afterText),limitN=Number(limitText),unreadText=c.req.query('unreadOnly');if(!/^\d+$/.test(afterText)||!/^\d+$/.test(limitText)||!Number.isInteger(after)||after<0||!Number.isInteger(limitN)||limitN<1||limitN>100||(unreadText!==undefined&&unreadText!=='true'&&unreadText!=='false'))throw new HttpError(400,'Invalid notification query');const unreadOnly=unreadText==='true',rows=await all<any>(c.get('config').DB.prepare('SELECT n.id,n.type,n.payload_json,n.created_at,nr.read_at FROM notification_recipients nr JOIN notifications n ON n.id=nr.notification_id WHERE nr.admin_user_id=? AND n.id>? ORDER BY n.id LIMIT ?').bind(c.get('claims').sub,after,limitN+1)),out=[] as any[];let cursor=after,barrier=false,processed=0;for(const r of rows){if(processed===limitN)break;if(!(await accessible(c.get('claims'),r.type))){barrier=true;break;}processed++;cursor=r.id;if(!unreadOnly||!r.read_at)out.push({id:r.id,type:r.type,payload:JSON.parse(r.payload_json),createdAt:r.created_at,read:Boolean(r.read_at)});}return c.json({success:true,data:out,nextCursor:cursor,hasMore:!barrier&&rows.length>processed});});
app.get('/api/notifications/status',auth,async c=>{const claims=c.get('claims'),db=c.get('config').DB,allowed:string[]=[];if(await accessible(claims,'new-request'))allowed.push('new-request');if(await accessible(claims,'expiry-alerts'))allowed.push('expiry-alerts');if(!allowed.length)return c.json({success:true,latestCursor:0,unreadCount:0});const marks=placeholders(allowed.length),row=await one<{latest:number;unread:number}>(db.prepare(`WITH barrier AS (SELECT min(n.id) id FROM notification_recipients nr JOIN notifications n ON n.id=nr.notification_id WHERE nr.admin_user_id=? AND n.type NOT IN (${marks})), visible AS (SELECT n.id,nr.read_at FROM notification_recipients nr JOIN notifications n ON n.id=nr.notification_id,barrier b WHERE nr.admin_user_id=? AND n.type IN (${marks}) AND (b.id IS NULL OR n.id<b.id)) SELECT coalesce(max(id),0) latest,coalesce(sum(read_at IS NULL),0) unread FROM visible`).bind(claims.sub,...allowed,claims.sub,...allowed));return c.json({success:true,latestCursor:row?.latest??0,unreadCount:row?.unread??0});});
app.post('/api/notifications/read-through',auth,async c=>{
  const body=await jsonBody(c);checkUnknown(body,['cursor','limit']);
  const target=Number(body.cursor),limitN=Number(body.limit??500);
  if(!Number.isInteger(target)||target<1||!Number.isInteger(limitN)||limitN<1||limitN>500)throw new HttpError(400,'Invalid cursor');
  const claims=c.get('claims'),db=c.get('config').DB,allowedTypes:string[]=[];
  if(await accessible(claims,'new-request'))allowedTypes.push('new-request');
  if(await accessible(claims,'expiry-alerts'))allowedTypes.push('expiry-alerts');
  const suppressed=await one<{id:number}>(db.prepare(`SELECT n.id FROM notification_recipients nr JOIN notifications n ON n.id=nr.notification_id WHERE nr.admin_user_id=? AND n.id<=?${allowedTypes.length?` AND n.type NOT IN (${placeholders(allowedTypes.length)})`:''} ORDER BY n.id LIMIT 1`).bind(claims.sub,target,...allowedTypes));
  const effectiveTarget=suppressed?Math.min(target,suppressed.id-1):target;
  const rows=allowedTypes.length?await all<{id:number}>(db.prepare(`SELECT n.id FROM notification_recipients nr JOIN notifications n ON n.id=nr.notification_id WHERE nr.admin_user_id=? AND n.id<=? AND nr.read_at IS NULL AND n.type IN (${placeholders(allowedTypes.length)}) ORDER BY n.id LIMIT ?`).bind(claims.sub,effectiveTarget,...allowedTypes,limitN+1)):[];
  const ids=rows.slice(0,limitN).map(row=>row.id);
  if(ids.length){const updates=chunkRows(ids,2,1).map(chunk=>db.prepare(`UPDATE notification_recipients SET read_at=? WHERE admin_user_id=? AND notification_id IN (${placeholders(chunk.length)})`).bind(nowIso(),claims.sub,...chunk));await batch(db,updates);}
  const remaining=allowedTypes.length?await one<{n:number}>(db.prepare(`SELECT count(*) n FROM notification_recipients nr JOIN notifications n ON n.id=nr.notification_id WHERE nr.admin_user_id=? AND nr.read_at IS NULL AND n.type IN (${placeholders(allowedTypes.length)})`).bind(claims.sub,...allowedTypes)):null;
  const highWater=allowedTypes.length?await one<{id:number}>(db.prepare(`SELECT max(n.id) id FROM notification_recipients nr JOIN notifications n ON n.id=nr.notification_id WHERE nr.admin_user_id=? AND n.id<=? AND n.type IN (${placeholders(allowedTypes.length)})`).bind(claims.sub,effectiveTarget,...allowedTypes)):null;
  return c.json({success:true,processedThrough:ids.at(-1)??highWater?.id??0,markedCount:ids.length,unreadCount:remaining?.n??0,hasMore:rows.length>limitN});
});
app.post('/api/notifications/:id/read',auth,async c=>{const key=id(c.req.param('id')),row=await one<{type:string}>(c.get('config').DB.prepare('SELECT n.type FROM notification_recipients nr JOIN notifications n ON n.id=nr.notification_id WHERE nr.admin_user_id=? AND n.id=?').bind(c.get('claims').sub,key));if(!row||!(await accessible(c.get('claims'),row.type)))throw new HttpError(404,'Not found');await run(c.get('config').DB.prepare('UPDATE notification_recipients SET read_at=coalesce(read_at,?) WHERE admin_user_id=? AND notification_id=?').bind(nowIso(),c.get('claims').sub,key));return c.json({success:true});});
app.get('/api/notifications/expiry-alerts',auth,requirePermission('ORGANIZATION','STAFF'),async c=>{const daysText=c.req.query('days')??'30',days=Number(daysText);if(!/^\d+$/.test(daysText)||!Number.isInteger(days)||days<0||days>365)throw new HttpError(400,'Invalid days');const {page,limit,offset}=listQuery(c),today=riyadhDate(new Date()),modifier=`+${days} days`,db=c.get('config').DB,where="(s.passport_expiry_date IS NOT NULL AND s.passport_expiry_date<=date(?,?)) OR (s.iqama_expiry_date IS NOT NULL AND s.iqama_expiry_date<=date(?,?))",total=await one<{n:number}>(db.prepare(`SELECT count(*) n FROM staff s WHERE ${where}`).bind(today,modifier,today,modifier)),rows=await all<{id:number;emp_code:string;name:string;store_code:string|null;passport_expiry_date:string|null;iqama_expiry_date:string|null}>(db.prepare(`SELECT s.id,s.emp_code,s.name,st.store_code,s.passport_expiry_date,s.iqama_expiry_date FROM staff s LEFT JOIN stores st ON st.id=s.store_id WHERE ${where} ORDER BY s.passport_expiry_date,s.iqama_expiry_date,s.id LIMIT ? OFFSET ?`).bind(today,modifier,today,modifier,limit,offset)),todayMs=Date.parse(`${today}T00:00:00.000Z`),thresholdMs=Date.parse(`${today}T00:00:00.000Z`)+days*86400000,data=rows.map(row=>{const notifications=[] as Array<{type:'expired'|'expiring_soon';field:string;expiryDate:string;status:'expired'|'expiring_soon';daysRemaining:number}>;for(const [field,value] of [['passportExpiryDate',row.passport_expiry_date],['iqamaExpiryDate',row.iqama_expiry_date]] as const)if(value){const expiryMs=Date.parse(`${value}T00:00:00.000Z`);if(expiryMs<=thresholdMs){const daysRemaining=Math.round((expiryMs-todayMs)/86400000),status=daysRemaining<=0?'expired' as const:'expiring_soon' as const;notifications.push({type:status,field,expiryDate:value,status,daysRemaining});}}return{staffId:row.id,empCode:row.emp_code,name:row.name,storeName:row.store_code,notifications};});return c.json({success:true,message:'Expiry alerts fetched successfully',count:total?.n??0,page,limit,totalPages:Math.ceil((total?.n??0)/limit),data});});
app.post('/api/notifications/expiry-runs/:businessDate/retry',auth,async c=>{await requireSuper(c);const requested=date(c.req.param('businessDate'));if(requested>riyadhDate(new Date()))throw new HttpError(400,'Future date');const runState=await one<{state:string;lease_expires_at:string|null}>(c.get('config').DB.prepare("SELECT state,lease_expires_at FROM scheduled_runs WHERE job_name='staff-expiry' AND business_date=?").bind(requested));if(!runState)throw new HttpError(404,'Run not found');if(runState.state==='completed'||(runState.state==='running'&&runState.lease_expires_at&&runState.lease_expires_at>nowIso()))throw new HttpError(409,'Run cannot be retried');try{return c.json(await runDailyExpiry(c.env,Date.now(),requested));}catch{throw new HttpError(409,'Run cannot be retried');}});

